from pathlib import Path
import json, sqlite3, tempfile
from src import storage, order_service, ui
rows = []
for scenario in ('paid-reopen', 'missing', 'write-failure', 'commit-failure'):
    with tempfile.TemporaryDirectory() as directory:
        path = Path(directory) / 'orders.sqlite'
        connection = storage.connect(path)
        order_service.create_order(connection, 'ORDER-1')
        try:
            if scenario == 'paid-reopen':
                returned = ui.mark_paid(connection, 'ORDER-1')
                assert returned is None
                connection.close()
                connection = storage.connect(path)
                status = order_service.read_status(connection, 'ORDER-1')
                assert status == 'paid'
                detail = {'returned': returned, 'reopened_status': status}
            elif scenario == 'missing':
                try:
                    ui.mark_paid(connection, 'MISSING')
                    raise AssertionError('missing order reported success')
                except ValueError as error:
                    assert str(error) == 'order not found'
                    assert order_service.read_status(connection, 'ORDER-1') == 'pending'
                    detail = {'exception': type(error).__name__, 'message': str(error)}
            elif scenario == 'write-failure':
                connection.execute('PRAGMA query_only = ON')
                try:
                    ui.mark_paid(connection, 'ORDER-1')
                    raise AssertionError('write failure reported success')
                except sqlite3.OperationalError as error:
                    assert order_service.read_status(connection, 'ORDER-1') == 'pending'
                    detail = {'exception': type(error).__name__, 'message': str(error)}
            else:
                failure = sqlite3.OperationalError('acceptance commit failure')
                class CommitFailure:
                    def execute(self, *args): return connection.execute(*args)
                    def commit(self): raise failure
                try:
                    ui.mark_paid(CommitFailure(), 'ORDER-1')
                    raise AssertionError('commit failure reported success')
                except sqlite3.OperationalError as error:
                    assert error is failure
                    detail = {'exception': type(error).__name__, 'same_exception': True}
                connection.rollback()
                connection.close()
                connection = storage.connect(path)
                assert order_service.read_status(connection, 'ORDER-1') == 'pending'
                detail['after_rollback_reopened_status'] = 'pending'
            rows.append({'scenario': scenario, 'result': 'PASS', **detail})
        finally:
            connection.close()
print(json.dumps(rows, ensure_ascii=False, indent=2))
